import re
from itertools import permutations

_MAX_NODES = 250000

_MONTHS = {
    'jan': 'january', 'feb': 'february', 'mar': 'march', 'apr': 'april',
    'may': 'may', 'jun': 'june', 'jul': 'july', 'aug': 'august',
    'sep': 'september', 'sept': 'september', 'oct': 'october',
    'nov': 'november', 'dec': 'december',
}
_INV_MONTHS = {
    'january': 'jan', 'february': 'feb', 'march': 'mar', 'april': 'apr',
    'may': 'may', 'june': 'jun', 'july': 'jul', 'august': 'aug',
    'september': 'sept', 'october': 'oct', 'november': 'nov',
    'december': 'dec',
}
_ORD = {'first': 1, 'second': 2, 'third': 3, 'fourth': 4,
        'fifth': 5, 'sixth': 6, 'seventh': 7}
_GAP = {'one': 2, 'two': 3, 'three': 4, 'four': 5}


def _norm(s):
    return re.sub(r'[^a-z0-9]+', ' ', s.lower()).strip()


def _tokens(text):
    return [(m.group(0), m.start(), m.end())
            for m in re.finditer(r'[a-z0-9]+', text.lower())]


def _part_match(nv, tok):
    if tok == nv or tok == nv + 's' or tok == nv + 'es':
        return True
    if nv.endswith('s') and tok == nv[:-1]:
        return True
    if nv in _MONTHS and tok == _MONTHS[nv]:
        return True
    if nv in _INV_MONTHS and tok == _INV_MONTHS[nv]:
        return True
    if (len(nv) >= 5 and nv.endswith('ing')):
        stem = nv[:-3]
        if tok == stem or tok == stem + 's':
            return True
    if (len(nv) >= 4 and nv.isalpha() and tok.isalpha()
            and tok.startswith(nv) and 0 < len(tok) - len(nv) <= 3):
        return True
    return False


def _nospace_and_map(text):
    ns = []
    cmap = []
    for i, ch in enumerate(text):
        c = ch.lower()
        if c.isalnum():
            ns.append(c)
            cmap.append(i)
    return ''.join(ns), cmap


def _match_span(nv, toks, nospace, cmap):
    """Return (start, end) char span of value nv in clue text, or None."""
    parts = nv.split()
    if not parts:
        return None
    if len(parts) == 1:
        for w, s, e in toks:
            if _part_match(parts[0], w):
                return (s, e)
        return None
    last_end = -1
    first = None
    last = None
    for p in parts:
        hit = None
        for w, s, e in toks:
            if s > last_end and _part_match(p, w):
                hit = (s, e)
                break
        if hit is None:
            tgt = ''.join(parts)
            idx = nospace.find(tgt)
            if idx < 0:
                return None
            s = cmap[idx]
            e = cmap[min(idx + len(tgt) - 1, len(cmap) - 1)] + 1
            hit = (s, e)
        if first is None:
            first = hit
        last = hit
        last_end = hit[1]
    return (first[0], last[1])


def _classify(clue, cats):
    low = ' ' + _norm(clue) + ' '
    toks = _tokens(clue)
    nospace, cmap = _nospace_and_map(clue)
    raw = []
    for ci in range(len(cats)):
        for vi, v in enumerate(cats[ci]):
            sp = _match_span(_norm(v), toks, nospace, cmap)
            if sp:
                raw.append({'s': sp[0], 'e': sp[1], 'ci': ci, 'vi': vi})
    # longest-match suppression: drop value matches strictly contained
    # in a longer matched span (e.g. 'tall' inside 'very tall')
    raw.sort(key=lambda m: (-(m['e'] - m['s']), m['s']))
    kept = []
    for m in raw:
        drop = False
        for k in kept:
            if (m['s'] >= k['s'] and m['e'] <= k['e']
                    and (m['e'] - m['s']) < (k['e'] - k['s'])):
                drop = True
                break
        if not drop:
            kept.append(m)
    kept.sort(key=lambda m: m['s'])
    ms = kept
    hm = re.search(r'\b(first|second|third|fourth|fifth|sixth|seventh)\s+house', low)
    house = None
    if hm:
        house = _ORD[hm.group(1)]
    else:
        hm2 = re.search(r'house\s+(\d)', low)
        if hm2:
            house = int(hm2.group(1))
    neg = re.search(r'\bnot\b', low) is not None
    gapm = re.search(r'\b(one|two|three|four)\s+houses?\s+between', low)
    positional = bool(gapm) or ('directly left of' in low
                                or 'directly right of' in low
                                or 'next to' in low or 'neighbor' in low
                                or 'left of' in low or 'right of' in low)
    if neg and positional:
        # negated positional clue: cannot be classified safely
        return None

    def pair():
        if len(ms) != 2:
            return None
        a, b = ms[0], ms[1]
        return a['ci'], a['vi'], b['ci'], b['vi']

    if gapm:
        pv = pair()
        if pv is None:
            return None
        c1, v1, c2, v2 = pv
        return {'type': 'gap', 'g': _GAP[gapm.group(1)],
                'ci': c1, 'vi': v1, 'cj': c2, 'vj': v2}
    if 'directly left of' in low:
        pv = pair()
        if pv is None:
            return None
        c1, v1, c2, v2 = pv
        return {'type': 'adjl', 'ci': c1, 'vi': v1, 'cj': c2, 'vj': v2}
    if 'directly right of' in low:
        pv = pair()
        if pv is None:
            return None
        c1, v1, c2, v2 = pv
        return {'type': 'adjr', 'ci': c1, 'vi': v1, 'cj': c2, 'vj': v2}
    if 'next to' in low or 'neighbor' in low:
        pv = pair()
        if pv is None:
            return None
        c1, v1, c2, v2 = pv
        return {'type': 'adj', 'ci': c1, 'vi': v1, 'cj': c2, 'vj': v2}
    if 'left of' in low:
        pv = pair()
        if pv is None:
            return None
        c1, v1, c2, v2 = pv
        return {'type': 'lt', 'ci': c1, 'vi': v1, 'cj': c2, 'vj': v2}
    if 'right of' in low:
        pv = pair()
        if pv is None:
            return None
        c1, v1, c2, v2 = pv
        return {'type': 'gt', 'ci': c1, 'vi': v1, 'cj': c2, 'vj': v2}
    if house is not None:
        if len(ms) == 1 and 1 <= house <= 6:
            m = ms[0]
            return {'type': 'ban' if neg else 'pin', 'ci': m['ci'],
                    'vi': m['vi'], 'h': house - 1}
        return None
    if len(ms) == 2 and re.search(r'\bis\b|\bare\b', low):
        a, b = ms[0], ms[1]
        return {'type': 'ne' if neg else 'eq', 'ci': a['ci'], 'vi': a['vi'],
                'cj': b['ci'], 'vj': b['vi']}
    return None


def _parse(view):
    q = view.get('question') or ''
    nm = re.search(r'There are (\d+) houses', q)
    if not nm:
        return None
    n = int(nm.group(1))
    if not (2 <= n <= 6):
        return None
    cats = []
    for line in q.splitlines():
        s = line.strip()
        if s.startswith('- '):
            vals = re.findall(r'`([^`]+)`', s)
            if vals:
                cats.append([v for v in vals])
    if not (2 <= len(cats) <= 6):
        return None
    clues = []
    in_clues = False
    for line in q.splitlines():
        if '## Clues' in line:
            in_clues = True
            continue
        if not in_clues:
            continue
        if line.startswith('#'):
            break
        m = re.match(r'\s*(\d+)\.\s+(.*)$', line)
        if m:
            clues.append((int(m.group(1)), m.group(2).strip()))
    return n, cats, clues


def _check(c, pa, pb):
    t = c['type']
    if t == 'eq':
        return pa == pb
    if t == 'ne':
        return pa != pb
    if t == 'adjl':
        return pa == pb - 1
    if t == 'adjr':
        return pa == pb + 1
    if t == 'adj':
        return abs(pa - pb) == 1
    if t == 'lt':
        return pa < pb
    if t == 'gt':
        return pa > pb
    if t == 'gap':
        return abs(pa - pb) == c['g']
    return False


def _solve(n, cats, cons):
    nc = len(cats)
    unary = [[] for _ in range(nc)]
    binary = []
    for c in cons:
        if c['type'] in ('pin', 'ban'):
            unary[c['ci']].append((c['vi'], c['h'], c['type'] == 'ban'))
        else:
            binary.append(c)
    perms = []
    for ci in range(nc):
        okp = []
        for perm in permutations(range(n)):
            good = True
            for vi, h, isban in unary[ci]:
                if (perm[vi] == h) != (not isban):
                    good = False
                    break
            if good:
                okp.append(perm)
        if not okp:
            return 0, None
        perms.append(okp)
    # arc consistency over value-position sets
    changed = True
    guard = 0
    while changed and guard < 60:
        guard += 1
        changed = False
        for c in binary:
            a, b = c['ci'], c['cj']
            if a == b:
                newa = [p for p in perms[a]
                        if _check(c, p[c['vi']], p[c['vj']])]
                if not newa:
                    return 0, None
                if len(newa) != len(perms[a]):
                    perms[a] = newa
                    changed = True
                continue
            pb = set(p[c['vj']] for p in perms[b])
            newa = [p for p in perms[a]
                    if any(_check(c, p[c['vi']], y) for y in pb)]
            if not newa:
                return 0, None
            if len(newa) != len(perms[a]):
                perms[a] = newa
                changed = True
            pa = set(p[c['vi']] for p in perms[a])
            newb = [p for p in perms[b]
                    if any(_check(c, x, p[c['vj']]) for x in pa)]
            if not newb:
                return 0, None
            if len(newb) != len(perms[b]):
                perms[b] = newb
                changed = True
    # per-category constraint index
    bycat = [[] for _ in range(nc)]
    for c in binary:
        bycat[c['ci']].append(c)
        bycat[c['cj']].append(c)
    order = sorted(range(nc), key=lambda ci: len(perms[ci]))
    assign = [None] * nc
    sols = []
    nodes = [0]

    def feasible(ci):
        for c in bycat[ci]:
            a, b = c['ci'], c['cj']
            if assign[a] is None or assign[b] is None:
                continue
            if not _check(c, assign[a][c['vi']], assign[b][c['vj']]):
                return False
        return True

    def dfs(k):
        nodes[0] += 1
        if nodes[0] > _MAX_NODES:
            raise RuntimeError('node budget exceeded')
        if k == nc:
            sols.append([list(p) if p is not None else None for p in assign])
            return len(sols) >= 2
        ci = order[k]
        for perm in perms[ci]:
            assign[ci] = perm
            if feasible(ci):
                if dfs(k + 1):
                    return True
        assign[ci] = None
        return False

    try:
        dfs(0)
    except RuntimeError:
        return -1, None
    if len(sols) == 1:
        return 1, [list(p) for p in sols[0]]
    return len(sols), None


def _cell(s):
    s = str(s)
    if len(s) > 37:
        s = s[:37] + '...'
    return s


def applies(view):
    try:
        parsed = _parse(view)
    except Exception:
        return False
    if parsed is None:
        return False
    n, cats, clues = parsed
    return len(clues) >= 3


def before_call(view, state):
    diag = []
    try:
        parsed = _parse(view)
        if parsed is None:
            diag.append('parse failed: house count or category lists not found')
            return {'diagnostics': diag}
        n, cats, clues = parsed
        if not clues:
            diag.append('no numbered clues found in question text')
            return {'diagnostics': diag}
        cons = []
        for num, text in clues:
            c = _classify(text, cats)
            if c is None:
                diag.append('clue %d unclassified: %s' % (num, text[:150]))
            else:
                c['num'] = num
                cons.append(c)
        if len(cons) != len(clues):
            return {'diagnostics': diag}
        count, sol = _solve(n, cats, cons)
        if count != 1 or sol is None:
            if count == -1:
                diag.append('search exceeded node budget; no note')
            else:
                diag.append('solutions found: %d; note only when unique' % count)
            return {'diagnostics': diag}
        for c in cons:
            if c['type'] in ('pin', 'ban'):
                continue
            if not _check(c, sol[c['ci']][c['vi']], sol[c['cj']][c['vj']]):
                diag.append('internal verify failed on clue %d; no note' % c['num'])
                return {'diagnostics': diag}
        cols = view.get('columns') or []
        names = []
        for i in range(len(cats)):
            nm2 = cols[i] if i < len(cols) and cols[i] else ('C%d' % (i + 1))
            names.append(_cell(nm2))
        table = [['House'] + names]
        for h in range(n):
            row = [str(h + 1)]
            for ci in range(len(cats)):
                vi = sol[ci].index(h)
                row.append(_cell(cats[ci][vi]))
            table.append(row)
        facts = [
            'Exhaustive backtracking over all %d numbered clues of this puzzle '
            'found exactly one grid satisfying every clue.' % len(clues),
            'The table below is that unique solution, computed from the '
            "puzzle's own category lists and clues.",
        ]
        diag.append('unique solution verified against all %d clues' % len(cons))
        return {'facts': facts, 'table': table, 'diagnostics': diag}
    except Exception as e:
        diag.append('error: %s' % str(e)[:180])
        return {'diagnostics': diag}
